// Because we don't have our own shader compiler (yet), these shaders are precompiled by Mesa (version 26.2.2-1~bpo13+0~rpt1).
// These prebuilt shaders require certain uniforms, which are generated by the generate_uniforms() function.

// Source vertex shader:
//   #version 300 es
//
//   layout(location = 0) in vec4 a_position;
//   layout(location = 1) in vec4 a_color;
//
//   uniform mat4 u_model_view_projection;
//
//   out vec4 v_color;
//
//   void main() {
//       gl_Position = u_model_view_projection * a_position;
//       v_color = a_color;
//   }

// Source fragment shader:
//   #version 300 es
//   precision highp float;
//
//   in vec4 v_color;
//
//   out vec4 f_color;
//
//   void main() {
//       f_color = v_color;
//   }

